import 'package:get/get.dart';

/// PiliNara UI translations.
///
/// - Keys are the original Chinese strings; call sites append `.tr` and
///   GetX falls back to the Chinese literal when no translation is
///   registered.
/// - `zh_CN` (Simplified Chinese) is the source of truth.
/// - `zh_TW` and `en_US` cover the bulk of the app's UI.
/// - Strings with `$variable` interpolation are NOT in these const
///   maps (they reference runtime values). Call sites must translate
///   those by splitting into static segments.
class AppTranslations extends Translations {
  @override
  Map<String, Map<String, String>> get keys => {
        'zh_CN': _zhCN,
        'zh_TW': _zhTW,
        'en_US': _enUS,
      };

  static const Map<String, String> _zhCN = {
