  static const Map<String, String> _zhTW = {
    '此功能追踪您跳过了哪些片段，让用户知道他们提交的片段帮助了多少人。同时点赞会作为依据，确保垃圾信息不会污染数据库。在您每次跳过片段时，我们都会向服务器发送一条消息。希望大家开启此项设置，以便得到更准确的统计数据。:)': '此功能追踪您跳过哪些片段,让使用者知道提交片段說明多少人.同时点赞會作為依据,确保垃圾資訊不會污染数据库.您每次跳过片段时,都會向服务器傳送一條消息.希望大家開啟此项設定,以便得到更准确统计数据.:)',
    '1. 【结构脉络】根据视频的话题转换，将其划分为几个清晰的章节，每个章节必须标明时间跨度（如 `[01:00] - [15:30]`）。\\n': '1. [结构脉络]根据影片话题转换,將其划分為几個清晰章节,每個章节必須标明时間跨度(如 `[01:00] - [15:30]`).\\n',
    '3. 【时间线速览】按时间顺序，提供一个简明的目录式大纲，每个条目必须以时间戳 `[mm:ss]` 开头。\\n': '3. [时間线速览]按时間顺序,提供一個简明目录式大纲,每個條目必須以时間戳 `[mm:ss]` 开头.\\n',
    '4. 【无字幕兜底策略】：如果你发现系统注入的"字幕"数据缺失（标记为"【警告：当前视频未提供字幕数据】"），': '4. [無字幕兜底策略]:如果发现系统注入"字幕"数据缺失(标记為"[警告:目前影片未提供字幕数据]"),',
    '你是一个视频内容分析与互动学习助手。当前对话已成功关联视频上下文。请严格基于注入的视频内容解答用户的疑问。\\n': '一個影片內容分析與互动学习助手.目前對话已成功关联影片上下文.請严格基于注入影片內容解答使用者疑问.\\n',
    '(嗯+|啊+|额+|呃+|那个|就是说|然后呢|对吧|是吧|对不对|你知道吗|反正就是|基本上|说实话)': '(嗯+|啊+|额+|呃+|那個|就说|然後呢|對吧|吧|對不對|知道吗|反正就|基本上|说实话)',
    '2. 只要输出内容涉及到具体的视频时间点，必须统一使用 [mm:ss] 或 [hh:mm:ss] 格式。': '2. 只要输出內容涉及到具体影片时間点,必須统一使用 [mm:ss] 或 [hh:mm:ss] 格式.',
    '请对这个视频进行极具深度的拆解分析。请克服长文本的省略倾向，尽可能保留具体细节、案例和逻辑推演。\\n': '請對這個影片進行极具深度拆解分析.請克服長文字省略倾向,尽可能保留具体细节,案例和逻辑推演.\\n',
    '标灰画质需要bilibili会员（已是会员？请关闭无痕模式）；4k和杜比视界播放效果可能不佳': '标灰画质需要bilibili會员(已會员?請關閉無痕模式);4k和杜比视界播放效果可能不佳',
    '2. 【深度提取】在每个章节下，详细阐述其核心观点、使用的论据（如有案例请务必写出）。\\n': '2. [深度提取]每個章节下,详细阐述其核心观点,使用论据(如有案例請务必写出).\\n',
    '加入黑名单后，将自动解除关注关系和对该用户的合集订阅关系，禁止该用户与我互动或查看我的空间': '加入黑名單',
    '视频中间简短提醒观众来一键三连或关注。 如果片段较长，或是有具体内容，则应分类为自我推广。': '影片',
    '仅用于对整个视频进行标记。适用于展示UP主免费或获得补贴后使用的产品、服务或场地的视频。': '仅用于對整個影片進行标记.适用于展示UP主免费或获得补贴後使用产品,服务或场地影片.',
    '你是一个智能问答助手。当前对话尚未关联任何视频内容。请使用你的通用知识库回答用户的问题。': '一個智能问答助手.目前對话尚未关联任何影片內容.請使用通用知識库回答使用者问题.',
    '请委婉地提示用户：『抱歉，您还没有载入视频信息，请先点击【载入上下文】按钮补充上下文。』': '請委婉地提示使用者:『抱歉,您还没有載入影片資訊,請先点击[載入上下文]按鈕补充上下文.』',
    '如 OpenAI …/v1、Gemini …/v1beta、火山方舟 …/api/v3': '如 OpenAI …/v1,Gemini …/v1beta,火山方舟 …/api/v3',
