  static const Map<String, String> _enUS = {
    '此功能追踪您跳过了哪些片段，让用户知道他们提交的片段帮助了多少人。同时点赞会作为依据，确保垃圾信息不会污染数据库。在您每次跳过片段时，我们都会向服务器发送一条消息。希望大家开启此项设置，以便得到更准确的统计数据。:)': '此功can追踪您跳过哪some段,让user知道Submit段help多少人.同时点赞will作for依据,确保垃圾info不will污染数据库.您每跳过段时,都willto服务器Sendone消息.hopelarge家Enable此项Set,以便得to更准确统计数据.:)',
    '1. 【结构脉络】根据视频的话题转换，将其划分为几个清晰的章节，每个章节必须标明时间跨度（如 `[01:00] - [15:30]`）。\\n': '1. [结构脉络]根据video话题转换,will其划分for几清晰章节,each章节must标明时between跨度(如 `[01:00] - [15:30]`).\\n',
    '3. 【时间线速览】按时间顺序，提供一个简明的目录式大纲，每个条目必须以时间戳 `[mm:ss]` 开头。\\n': '3. [时between线速览]按时between顺序,提供one简明目录式large纲,each目must以时between戳 `[mm:ss]` 开头.\\n',
    '4. 【无字幕兜底策略】：如果你发现系统注入的"字幕"数据缺失（标记为"【警告：当前视频未提供字幕数据】"），': '4. [none字幕兜底策略]:if发现系统注入"字幕"数据缺失(标记for"[warning:currentvideonot提供字幕数据]"),',
    '你是一个视频内容分析与互动学习助手。当前对话已成功关联视频上下文。请严格基于注入的视频内容解答用户的疑问。\\n': 'onevideoin容分析and互动学习助手.currentcorrect话alreadysuccess关联videoupdown文.please严格基于注入videoin容解答user疑问.\\n',
    '(嗯+|啊+|额+|呃+|那个|就是说|然后呢|对吧|是吧|对不对|你知道吗|反正就是|基本上|说实话)': '(嗯+|啊+|额+|呃+|that|就说|然back呢|correct吧|吧|correct不correct|知道吗|反正就|基本up|说实话)',
    '2. 只要输出内容涉及到具体的视频时间点，必须统一使用 [mm:ss] 或 [hh:mm:ss] 格式。': '2. 只will输出in容涉andto具体video时between点,must统one使用 [mm:ss] or [hh:mm:ss] 格式.',
    '请对这个视频进行极具深度的拆解分析。请克服长文本的省略倾向，尽可能保留具体细节、案例和逻辑推演。\\n': 'pleasecorrectthisvideoin progress极具deep度拆解分析.please克服longtext省略倾to,尽可can保留具体细节,案例and逻辑推演.\\n',
    '标灰画质需要bilibili会员（已是会员？请关闭无痕模式）；4k和杜比视界播放效果可能不佳': '标灰画质needbilibiliwill员(alreadywill员?pleaseClosenone痕模式);4kandDolby视界播放效果可can不佳',
    '2. 【深度提取】在每个章节下，详细阐述其核心观点、使用的论据（如有案例请务必写出）。\\n': '2. [deep度提取]each章节down,详细阐述其核心观点,使用论据(如yes案例please务必写出).\\n',
    '加入黑名单后，将自动解除关注关系和对该用户的合集订阅关系，禁止该用户与我互动或查看我的空间': 'Add to blacklist',
